BEGIN;

CREATE TABLE xp_accounts (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, lifetime_xp BIGINT NOT NULL DEFAULT 0 CHECK(lifetime_xp>=0), current_xp BIGINT NOT NULL DEFAULT 0 CHECK(current_xp>=0), updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE xp_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, amount INTEGER NOT NULL, reason VARCHAR(80) NOT NULL, source_type VARCHAR(80), source_id UUID, idempotency_key VARCHAR(160) NOT NULL UNIQUE, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX xp_events_user_idx ON xp_events(user_id,created_at DESC);
CREATE TABLE levels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(60) NOT NULL UNIQUE, min_xp BIGINT NOT NULL UNIQUE CHECK(min_xp>=0), badge_media_id UUID REFERENCES media_assets(id), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE level_translations (level_id UUID NOT NULL REFERENCES levels(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), name TEXT NOT NULL, description TEXT, PRIMARY KEY(level_id,locale));
CREATE TABLE achievements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(80) NOT NULL UNIQUE, icon_media_id UUID REFERENCES media_assets(id), criteria_json JSONB NOT NULL DEFAULT '{}', xp_reward INTEGER NOT NULL DEFAULT 0 CHECK(xp_reward>=0), status "PublicationStatus" NOT NULL DEFAULT 'DRAFT');
CREATE TABLE achievement_translations (achievement_id UUID NOT NULL REFERENCES achievements(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), name TEXT NOT NULL, description TEXT, PRIMARY KEY(achievement_id,locale));
CREATE TABLE user_achievements (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, achievement_id UUID NOT NULL REFERENCES achievements(id) ON DELETE RESTRICT, awarded_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), source_type VARCHAR(80), source_id UUID, PRIMARY KEY(user_id,achievement_id));
CREATE TABLE user_streaks (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, current_days INTEGER NOT NULL DEFAULT 0 CHECK(current_days>=0), longest_days INTEGER NOT NULL DEFAULT 0 CHECK(longest_days>=0), last_activity_date DATE, updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE streak_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_date DATE NOT NULL, event_type VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), UNIQUE(user_id,activity_date,event_type));
CREATE TABLE leaderboard_periods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(80) NOT NULL UNIQUE, starts_at TIMESTAMPTZ(3) NOT NULL, ends_at TIMESTAMPTZ(3) NOT NULL, scope VARCHAR(30) NOT NULL DEFAULT 'GLOBAL', scope_id UUID, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', CHECK(ends_at>starts_at));
CREATE TABLE leaderboard_entries (period_id UUID NOT NULL REFERENCES leaderboard_periods(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, score BIGINT NOT NULL DEFAULT 0, rank INTEGER, updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), PRIMARY KEY(period_id,user_id));

CREATE TABLE games (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug VARCHAR(160) NOT NULL UNIQUE, type VARCHAR(40) NOT NULL, cover_media_id UUID REFERENCES media_assets(id), rules_json JSONB NOT NULL DEFAULT '{}', status "PublicationStatus" NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE game_translations (game_id UUID NOT NULL REFERENCES games(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), title TEXT NOT NULL, description TEXT, PRIMARY KEY(game_id,locale));
CREATE TABLE game_levels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), game_id UUID NOT NULL REFERENCES games(id) ON DELETE CASCADE, position INTEGER NOT NULL, config_json JSONB NOT NULL DEFAULT '{}', max_score INTEGER, UNIQUE(game_id,position));
CREATE TABLE game_level_translations (level_id UUID NOT NULL REFERENCES game_levels(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), title TEXT NOT NULL, instructions TEXT, PRIMARY KEY(level_id,locale));
CREATE TABLE game_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), game_id UUID NOT NULL REFERENCES games(id) ON DELETE RESTRICT, level_id UUID REFERENCES game_levels(id) ON DELETE RESTRICT, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, score INTEGER NOT NULL DEFAULT 0, result_json JSONB NOT NULL DEFAULT '{}', started_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ(3));
CREATE TABLE coding_challenges (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug VARCHAR(160) NOT NULL UNIQUE, difficulty SMALLINT CHECK(difficulty BETWEEN 1 AND 5), starter_code JSONB NOT NULL DEFAULT '{}', tests_encrypted TEXT NOT NULL, time_limit_ms INTEGER NOT NULL DEFAULT 2000 CHECK(time_limit_ms>0), memory_limit_mb INTEGER NOT NULL DEFAULT 256 CHECK(memory_limit_mb>0), status "PublicationStatus" NOT NULL DEFAULT 'DRAFT');
CREATE TABLE coding_challenge_translations (challenge_id UUID NOT NULL REFERENCES coding_challenges(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), title TEXT NOT NULL, statement TEXT NOT NULL, PRIMARY KEY(challenge_id,locale));
CREATE TABLE coding_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), challenge_id UUID NOT NULL REFERENCES coding_challenges(id) ON DELETE RESTRICT, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, language VARCHAR(40) NOT NULL, source_code TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'QUEUED', score INTEGER, execution_ms INTEGER, memory_kb INTEGER, result_json JSONB NOT NULL DEFAULT '{}', submitted_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());

CREATE TABLE hackathons (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug VARCHAR(180) NOT NULL UNIQUE, cover_media_id UUID REFERENCES media_assets(id), registration_opens_at TIMESTAMPTZ(3), registration_closes_at TIMESTAMPTZ(3), starts_at TIMESTAMPTZ(3) NOT NULL, ends_at TIMESTAMPTZ(3) NOT NULL, team_min_size INTEGER NOT NULL DEFAULT 1 CHECK(team_min_size>0), team_max_size INTEGER NOT NULL DEFAULT 5 CHECK(team_max_size>=team_min_size), status "PublicationStatus" NOT NULL DEFAULT 'DRAFT', rules_json JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE hackathon_translations (hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), title TEXT NOT NULL, short_description TEXT, description TEXT, rules_text TEXT, PRIMARY KEY(hackathon_id,locale));
CREATE TABLE hackathon_tracks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, code VARCHAR(80) NOT NULL, sponsor_id UUID REFERENCES companies(id), sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(hackathon_id,code));
CREATE TABLE hackathon_track_translations (track_id UUID NOT NULL REFERENCES hackathon_tracks(id) ON DELETE CASCADE, locale VARCHAR(10) NOT NULL CHECK(locale IN ('ru','ky','en')), name TEXT NOT NULL, description TEXT, PRIMARY KEY(track_id,locale));
CREATE TABLE hackathon_registrations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE RESTRICT, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED','CANCELLED')), experience_json JSONB NOT NULL DEFAULT '{}', consent_version_id UUID REFERENCES legal_document_versions(id), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), UNIQUE(hackathon_id,user_id));
CREATE TABLE hackathon_teams (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, track_id UUID REFERENCES hackathon_tracks(id) ON DELETE SET NULL, name VARCHAR(160) NOT NULL, invite_code VARCHAR(80) NOT NULL UNIQUE, captain_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status VARCHAR(20) NOT NULL DEFAULT 'FORMING', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), UNIQUE(hackathon_id,name));
CREATE TABLE hackathon_team_members (team_id UUID NOT NULL REFERENCES hackathon_teams(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role VARCHAR(20) NOT NULL DEFAULT 'MEMBER', joined_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), left_at TIMESTAMPTZ(3), PRIMARY KEY(team_id,user_id));
CREATE TABLE hackathon_projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), team_id UUID NOT NULL UNIQUE REFERENCES hackathon_teams(id) ON DELETE CASCADE, title VARCHAR(240) NOT NULL, description TEXT NOT NULL, repository_url TEXT, demo_url TEXT, presentation_media_id UUID REFERENCES media_assets(id), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', submitted_at TIMESTAMPTZ(3), updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE hackathon_project_files (project_id UUID NOT NULL REFERENCES hackathon_projects(id) ON DELETE CASCADE, media_id UUID NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT, PRIMARY KEY(project_id,media_id));
CREATE TABLE hackathon_judges (hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, track_id UUID REFERENCES hackathon_tracks(id) ON DELETE SET NULL, PRIMARY KEY(hackathon_id,user_id));
CREATE TABLE hackathon_criteria (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, name VARCHAR(180) NOT NULL, max_score NUMERIC(8,2) NOT NULL CHECK(max_score>0), weight NUMERIC(6,3) NOT NULL DEFAULT 1 CHECK(weight>0), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE hackathon_scores (project_id UUID NOT NULL REFERENCES hackathon_projects(id) ON DELETE CASCADE, judge_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, criterion_id UUID NOT NULL REFERENCES hackathon_criteria(id) ON DELETE RESTRICT, score NUMERIC(8,2) NOT NULL CHECK(score>=0), comment TEXT, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), PRIMARY KEY(project_id,judge_id,criterion_id));
CREATE TABLE hackathon_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, project_id UUID NOT NULL REFERENCES hackathon_projects(id) ON DELETE RESTRICT, track_id UUID REFERENCES hackathon_tracks(id) ON DELETE SET NULL, place INTEGER NOT NULL CHECK(place>0), total_score NUMERIC(12,3) NOT NULL, published_at TIMESTAMPTZ(3), UNIQUE(hackathon_id,track_id,place));
CREATE TABLE hackathon_prizes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hackathon_id UUID NOT NULL REFERENCES hackathons(id) ON DELETE CASCADE, track_id UUID REFERENCES hackathon_tracks(id) ON DELETE SET NULL, place INTEGER, title VARCHAR(180) NOT NULL, value_minor BIGINT CHECK(value_minor>=0), currency CHAR(3), sponsor_id UUID REFERENCES companies(id));
CREATE TABLE hackathon_awards (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), prize_id UUID NOT NULL REFERENCES hackathon_prizes(id) ON DELETE RESTRICT, team_id UUID NOT NULL REFERENCES hackathon_teams(id) ON DELETE RESTRICT, awarded_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), UNIQUE(prize_id,team_id));

CREATE TABLE audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id UUID, before_data JSONB, after_data JSONB, ip_hash VARCHAR(128), request_id VARCHAR(100), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX audit_logs_entity_idx ON audit_logs(entity_type,entity_id,created_at DESC);
CREATE INDEX audit_logs_actor_idx ON audit_logs(actor_id,created_at DESC);
CREATE TABLE security_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id) ON DELETE SET NULL, event_type VARCHAR(100) NOT NULL, severity VARCHAR(10) NOT NULL CHECK(severity IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL')), ip_hash VARCHAR(128), user_agent TEXT, payload JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type VARCHAR(100) NOT NULL, aggregate_id UUID NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSONB NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempt_count INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ(3), last_error TEXT, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_events(available_at) WHERE status='PENDING';
CREATE TABLE integrations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(80) NOT NULL UNIQUE, provider VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', credentials_encrypted TEXT, config JSONB NOT NULL DEFAULT '{}', updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE webhook_endpoints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), integration_id UUID REFERENCES integrations(id) ON DELETE CASCADE, url TEXT NOT NULL, secret_encrypted TEXT NOT NULL, event_types JSONB NOT NULL DEFAULT '[]', is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), endpoint_id UUID NOT NULL REFERENCES webhook_endpoints(id) ON DELETE CASCADE, event_id UUID REFERENCES outbox_events(id) ON DELETE SET NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', response_status INTEGER, response_body TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ(3), delivered_at TIMESTAMPTZ(3), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE background_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), queue VARCHAR(80) NOT NULL, name VARCHAR(120) NOT NULL, payload JSONB NOT NULL DEFAULT '{}', status VARCHAR(20) NOT NULL DEFAULT 'QUEUED', priority INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 5, run_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), locked_at TIMESTAMPTZ(3), locked_by VARCHAR(160), finished_at TIMESTAMPTZ(3), last_error TEXT, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX background_jobs_ready_idx ON background_jobs(queue,priority DESC,run_at) WHERE status='QUEUED';
CREATE TABLE data_exports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requested_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, kind VARCHAR(80) NOT NULL, filters JSONB NOT NULL DEFAULT '{}', status VARCHAR(20) NOT NULL DEFAULT 'QUEUED', result_media_id UUID REFERENCES media_assets(id), expires_at TIMESTAMPTZ(3), created_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ(3));
CREATE TABLE backup_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, started_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ(3), location TEXT, size_bytes BIGINT, checksum VARCHAR(128), error TEXT);
CREATE TABLE analytics_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), anonymous_id VARCHAR(128), user_id UUID REFERENCES users(id) ON DELETE SET NULL, session_id VARCHAR(128), event_name VARCHAR(100) NOT NULL, page_path TEXT, properties JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE INDEX analytics_events_name_time_idx ON analytics_events(event_name,occurred_at DESC);
CREATE TABLE daily_metrics (metric_date DATE NOT NULL, metric_name VARCHAR(100) NOT NULL, dimensions JSONB NOT NULL DEFAULT '{}', value NUMERIC(20,4) NOT NULL, calculated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), PRIMARY KEY(metric_date,metric_name,dimensions));
CREATE TABLE feature_flags (key VARCHAR(120) PRIMARY KEY, description TEXT, enabled BOOLEAN NOT NULL DEFAULT false, rollout_percent SMALLINT NOT NULL DEFAULT 0 CHECK(rollout_percent BETWEEN 0 AND 100), rules JSONB NOT NULL DEFAULT '[]', updated_by UUID REFERENCES users(id), updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE TABLE search_documents (entity_type VARCHAR(80) NOT NULL, entity_id UUID NOT NULL, locale VARCHAR(10) NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, search_vector TSVECTOR GENERATED ALWAYS AS (setweight(to_tsvector('simple',coalesce(title,'')),'A') || setweight(to_tsvector('simple',coalesce(body,'')),'B')) STORED, updated_at TIMESTAMPTZ(3) NOT NULL DEFAULT now(), PRIMARY KEY(entity_type,entity_id,locale));
CREATE INDEX search_documents_fts_idx ON search_documents USING GIN(search_vector);

COMMIT;
